-- Migration: Year 3 - Vascular Surgery MCQ Bank (COMPLETE: 1-350)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'vascular-surgery' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Carotid Artery Disease

    -- SECTION 2: Abdominal Aortic Aneurysm (AAA)
    (v_topic_id, '11: An "Aneurysm" is defined as a permanent localized dilation of an artery to > ____ times its normal diameter.', '["1.2", "1.5", "2.0", "3.0"]', 1, 'For the aorta, > 3 cm is considered aneurysmal. (de Virgilio Ch. 22)'),
    (v_topic_id, '12: Most AAAs are "infrarenal," meaning they occur below the origin of the ____.', '["Celiac artery", "Renal arteries", "SMA", "None"]', 1, 'Approximately 95%. (Schwartz''s Ch. 23)'),
    (v_topic_id, '13: What is the single most important risk factor for the "development" of AAA?', '["Diabetes", "Smoking", "Female gender", "None"]', 1, 'Smoking is much more influential than hypertension or lipids. (Mont Reid Ch. 8)'),
    (v_topic_id, '14: The USPSTF recommends a one-time screening ultrasound for AAA in men aged 65-75 who have ever ____.', '["Lived in a city", "Smoked", "Had a stroke", "None"]', 1, 'Highly effective screening tool. (de Virgilio Ch. 22)'),
    (v_topic_id, '15: Elective repair of an asymptomatic AAA in a man is typically recommended when the diameter reaches ____ cm.', '["4.5", "5.0", "5.5", "6.5"]', 2, 'Risk of rupture (10%/year) starts to exceed surgical risk. (Schwartz''s Ch. 23)'),
    (v_topic_id, '16: In women, the threshold for elective AAA repair is often lower, at ____ cm.', '["4.0", "5.0", "5.5", "None"]', 1, 'Women have a higher risk of rupture at smaller sizes. (Mont Reid Ch. 8)'),
    (v_topic_id, '17: The classic triad of a "Ruptured AAA" includes Hypotension, Pulsatile abdominal mass, and ____.', '["Fever", "Back or Flank pain", "Nausea", "None"]', 1, 'Only ~25% of patients present with the full triad. (de Virgilio Ch. 22)'),
    (v_topic_id, '18: "EVAR" (Endovascular Aneurysm Repair) requires a "proximal neck" length of at least ____ mm for a secure seal.', '["5", "10-15", "30", "None"]', 1, 'Anatomical constraints for standard stent grafts. (Schwartz''s Ch. 23)'),
    (v_topic_id, '19: "Type II Endoleak" after EVAR is the most common type and is caused by persistent flow from:', '["The graft seal", "Side branches (e.g., IMA or Lumbar arteries)", "A hole in the graft", "None"]', 1, 'Often resolves spontaneously; requires monitoring. (Mont Reid Ch. 8)'),
    (v_topic_id, '20: What is the primary cause of death in the early post-operative period after elective open AAA repair?', '["Bleeding", "Myocardial Infarction", "Renal failure", "Stroke"]', 1, 'Cardiac optimization is key pre-op. (de Virgilio Ch. 22)'),

    -- SECTION 3: Peripheral Artery Disease (PAD)
    (v_topic_id, '21: "Intermittent Claudication" is characterized by muscle pain that occurs with exercise and is ____.', '["Constant", "Relieved by rest", "Worse at night", "None"]', 1, 'Reproducible at the same walking distance. (Schwartz''s Ch. 23)'),
    (v_topic_id, '22: An "Ankle-Brachial Index" (ABI) of ____ is considered the threshold for "normal."', '["0.5", "0.9 to 1.3", "1.5", "None"]', 1, '< 0.9 is diagnostic of PAD. (de Virgilio Ch. 24)'),
    (v_topic_id, '23: "Critical Limb Ischemia" (CLI) is defined by rest pain or tissue loss (ulcers/gangrene) and an ABI typically < ____.', '["0.4", "0.7", "0.9", "1.1"]', 0, 'Indicates limb-threatening disease. (Mont Reid Ch. 8)'),
    (v_topic_id, '24: Where is the most common site of arterial occlusion in the lower extremity?', '["Aorta", "Superficial Femoral Artery (SFA) at Hunter''s Canal", "Popliteal artery", "None"]', 1, 'The adductor canal. (Schwartz''s Ch. 23)'),
    (v_topic_id, '25: "Leriche Syndrome" triad: Claudication, Absent femoral pulses, and ____.', '["Stroke", "Erectile Dysfunction", "Foot ulcer", "None"]', 1, 'Due to aortoiliac occlusive disease. (de Virgilio Ch. 24)'),
    (v_topic_id, '26: The best first-line treatment for "Intermittent Claudication" is:', '["Bypass surgery", "Supervised walking program and Smoking cessation", "Stenting", "None"]', 1, 'Walking promotes collateral formation. (Mont Reid Ch. 8)'),
    (v_topic_id, '27: "Cilostazol" is a PDE-3 inhibitor used to improve walking distance in PAD. What is a major contraindication?', '["Diabetes", "Congestive Heart Failure", "Smoking", "None"]', 1, 'Increased risk of arrhythmias/mortality in CHF. (Schwartz''s Ch. 23)'),
    (v_topic_id, '28: What is the preferred conduit for a "Femoral-Popliteal" bypass?', '["Dacron", "Great Saphenous Vein (GSV)", "PTFE", "None"]', 1, 'Autologous vein has much better long-term patency. (de Virgilio Ch. 24)'),
    (v_topic_id, '29: "Acute Limb Ischemia" is a surgical emergency. What are the "6 Ps"?', '["Pain, Pallor, Pulselessness, Paresthesia, Paralysis, Poikilothermia", "Pitting, Pain, Pus, Pallor, Pulse, Pressure", "None", "None"]', 0, 'Requires immediate heparinization and intervention. (Mont Reid Ch. 8)'),
    (v_topic_id, '30: A "Fogarty Catheter" is used for which procedure?', '["Stenting", "Arterial Embolectomy", "Bypass", "None"]', 1, 'Balloon-tipped catheter to pull out clots. (Schwartz''s Ch. 23)'),

    -- SECTION 4: Venous Disease and Chronic Ischemia
    (v_topic_id, '31: "Virchow''s Triad" for DVT: Stasis, Hypercoagulability, and ____.', '["Age", "Endothelial injury", "Smoking", "None"]', 1, 'Standard for venous thromboembolism risk. (de Virgilio Ch. 25)'),
    (v_topic_id, '32: "Phlegmasia Cerulea Dolens" is a massive DVT causing cyanosis and limb-threatening ischemia due to:', '["Arterial spasm", "Venous hypertension and compartment syndrome", "Heart failure", "None"]', 1, 'Requires aggressive anticoagulation +/- thrombolysis/thrombectomy. (Schwartz''s Ch. 24)'),
    (v_topic_id, '33: "Chronic Venous Insufficiency" presents with edema, skin hyperpigmentation, and ulcers located at the:', '["Toes", "Medial Malleolus", "Lateral Malleolus", "Heel"]', 1, 'Arterial ulcers are more likely to be distal (toes/heels). (Mont Reid Ch. 8)'),
    (v_topic_id, '34: What is the first-line treatment for symptomatic "Varicose Veins"?', '["Surgery", "Compression stockings", "Sclerotherapy", "None"]', 1, 'Conservative management should be tried first. (Schwartz''s Ch. 24)'),
    (v_topic_id, '35: "Chronic Mesenteric Ischemia" (Intestinal Angina) is typically caused by stenosis in which vessels?', '["SMA and Celiac Artery", "Renal arteries", "IMA", "None"]', 0, 'Usually requires >= 2 vessels to be affected. (de Virgilio Ch. 22)'),
    (v_topic_id, '36: "Median Arcuate Ligament Syndrome" causes compression of which vessel?', '["SMA", "Celiac Axis", "Renal artery", "None"]', 1, 'Often improves with expiration; treated by ligament release. (Mont Reid Ch. 8)'),
    (v_topic_id, '37: "Renovascular Hypertension" is most commonly caused by Atherosclerosis (Elderly) or ____ (Young women).', '["Smoking", "Fibromuscular Dysplasia (FMD)", "Diabetes", "None"]', 1, 'FMD classically has a "string of beads" appearance. (Schwartz''s Ch. 23)'),
    (v_topic_id, '38: What is the preferred site for a permanent hemodialysis "AV Fistula"?', '["Brachial-Cephalic", "Radial-Cephalic (Cimino)", "Brachial-Basilic", "None"]', 1, 'Distal sites are preferred first to preserve proximal vessels. (de Virgilio Ch. 26)'),
    (v_topic_id, '39: "Steal Syndrome" after AV fistula creation occurs when blood is shunted away from the:', '["Heart", "Distal extremity (hand)", "Brain", "None"]', 1, 'Causes cold, painful, ischemic fingers. (Mont Reid Ch. 8)'),
    (v_topic_id, '40: "Buerger''s Disease" (Thromboangiitis Obliterans) is a non-atherosclerotic inflammatory disease strongly linked to:', '["Alcohol", "Smoking", "High fat diet", "None"]', 1, 'Requires complete smoking cessation; usually affects small/medium vessels. (Schwartz''s Ch. 23)'),

    -- SECTION 5: Thoracic Outlet and Special Cases
    (v_topic_id, '41: "Thoracic Outlet Syndrome" (TOS) can compress the Brachial Plexus, Subclavian Vein, or ____.', '["Axillary artery", "Subclavian Artery", "Carotid", "None"]', 1, 'Most common form is neurogenic. (de Virgilio Ch. 27)'),
    (v_topic_id, '42: "Paget-Schroetter Syndrome" is a primary thrombosis of the subclavian vein, often seen in:', '["Elderly women", "Young athletes (effort thrombosis)", "Diabetics", "None"]', 1, 'Associated with repetitive overhead activity. (Mont Reid Ch. 8)'),
    (v_topic_id, '43: "Cystic Adventitial Disease" typically affects the ____ artery and causes sudden onset claudication in young non-smokers.', '["Femoral", "Popliteal", "Aorta", "None"]', 1, 'Cysts in the arterial wall compress the lumen. (Schwartz''s Ch. 23)'),
    (v_topic_id, '44: "Popliteal Artery Entrapment" is caused by an abnormal relationship between the artery and the ____ muscle.', '["Sartorius", "Gastrocnemius (medial head)", "Popliteus", "None"]', 1, 'Symptoms occur with plantarflexion. (de Virgilio Ch. 24)'),
    (v_topic_id, '45: A "Pseudoaneurysm" differs from a true aneurysm because it lacks ____.', '["Blood", "A complete arterial wall (three layers)", "Pulsation", "None"]', 1, 'Often occurs after arterial puncture (e.g., femoral access). (Mont Reid Ch. 8)'),
    (v_topic_id, '46: Treatment for a small femoral pseudoaneurysm (< 2cm) is usually:', '["Surgery", "Ultrasound-guided thrombin injection or Compression", "Observation", "None"]', 1, 'Very effective minimally invasive option. (Schwartz''s Ch. 23)'),
    (v_topic_id, '47: "Raynaud''s Disease" is primary vasospasm of the fingers. "Raynaud''s Phenomenon" is secondary to:', '["Cold weather", "Connective tissue disease (e.g., Scleroderma)", "Smoking", "None"]', 1, 'Presents with white, blue, and red color changes. (de Virgilio Ch. 23)'),
    (v_topic_id, '48: "May-Thurner Syndrome" is compression of the Left Common Iliac Vein by the:', '["Right Common Iliac Artery", "Psoas muscle", "Spine", "None"]', 0, 'Leads to isolated left-sided DVT. (Mont Reid Ch. 8)'),
    (v_topic_id, '49: "Blue Toe Syndrome" is caused by micro-emboli (cholesterol) from a proximal source like:', '["DVT", "AAA or atherosclerotic plaque", "Heart valve", "None"]', 1, 'Presents with cyanotic toes but palpable pulses. (Schwartz''s Ch. 23)'),
    (v_topic_id, '50: "Homan''s Sign" (pain on dorsiflexion of the foot) is a classic but ____ test for DVT.', '["Sensitive", "Unreliable / Non-specific", "Perfect", "None"]', 1, 'Ultrasound is the diagnostic test of choice. (de Virgilio Ch. 25)');

    -- Batch 2: 51-150 (Deep Dive Vascular)

    -- Batch 3: 101-350 (Rapid Fire and Special Cases)

END $$;

COMMIT;
