    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the most common site of atherosclerotic plaque in the carotid system?', '["Common Carotid Artery", "Carotid Bifurcation (Internal Carotid origin)", "External Carotid Artery", "None"]', 1, 'Turbulence at the bifurcation promotes plaque formation. (Schwartz''s Ch. 23)'),
    (v_topic_id, '2: "Amaurosis Fugax" (painless, transient vision loss in one eye) is described as a "curtain coming down" and indicates an embolus to the:', '["Ophthalmic artery", "Retinal artery", "Middle cerebral artery", "None"]', 1, 'A classic warning sign of carotid disease. (de Virgilio Ch. 23)'),
    (v_topic_id, '3: According to NASCET, "Carotid Endarterectomy" (CEA) is strongly indicated for "Symptomatic" patients with stenosis > ____%.', '["30", "50", "70", "90"]', 2, 'Significant benefit for symptomatic >= 70% stenosis. (Mont Reid Ch. 8)'),
    (v_topic_id, '4: For "Asymptomatic" patients, CEA is generally considered if stenosis is > ____% in high-risk individuals.', '["40", "60", "80", "None"]', 1, 'ACAS/ACST trials. (Schwartz''s Ch. 23)'),
    (v_topic_id, '5: During CEA, the "shunting" decision is often based on "stump pressure" < ____ mmHg.', '["25", "50", "75", "100"]', 1, 'Measures collateral flow via the Circle of Willis. (de Virgilio Ch. 23)'),
    (v_topic_id, '6: Which nerve is at risk during CEA and leads to tongue deviation toward the side of injury?', '["Vagus Nerve", "Hypoglossal Nerve (CN XII)", "Glossopharyngeal Nerve", "None"]', 1, 'Located superior to the bifurcation. (Mont Reid Ch. 8)'),
    (v_topic_id, '7: Injury to the "Ansa Cervicalis" during CEA results in:', '["Hoarseness", "Tongue deviation", "No significant clinical deficit", "None"]', 2, 'Commonly sacrificed to mobilize the carotid; innervates infrahyoid muscles. (Schwartz''s Ch. 23)'),
    (v_topic_id, '8: The most common cause of "Perioperative Stroke" during/after CEA is:', '["Hypotension", "Embolization or Thrombosis", "Hemorrhage", "None"]', 1, 'Technical error or plaque rupture. (de Virgilio Ch. 23)'),
    (v_topic_id, '9: "Carotid Stenting" (CAS) is preferred over CEA in which patient population?', '["Young healthy patients", "Patients with hostile necks (prior radiation or surgery)", "Elderly", "None"]', 1, 'Avoids the risks of a complex surgical dissection. (Mont Reid Ch. 8)'),
    (v_topic_id, '10: "Post-CEA Hypertension" is common due to trauma to the ____.', '["Celiac plexus", "Carotid sinus (Baroreceptors)", "Vagus nerve", "None"]', 1, 'Requires careful BP control to prevent hyperperfusion syndrome. (Schwartz''s Ch. 23)'),
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Aorta" - How many layers?', '["1", "2", "3 (Intima, Media, Adventitia)", "4"]', 2, 'Anatomy. (Schwartz''s Ch. 23)'),
    (v_topic_id, '52: "Vasa Vasorum" are small vessels that supply the ____.', '["Nerves", "Adventitia of large arteries", "Muscles", "None"]', 1, 'Important for aortic health. (de Virgilio Ch. 22)'),
    (v_topic_id, '53: "Thoracic Aortic Aneurysm" (TAA) - most common cause?', '["Smoking", "Cystic Medial Necrosis / Hypertension", "Trauma", "None"]', 1, 'Marfan syndrome link. (Mont Reid Ch. 8)'),
    (v_topic_id, '54: "Aortic Dissection" - Type A?', '["Involves Ascending Aorta", "Surgical Emergency", "Both", "None"]', 2, 'Stanford Classification. (Schwartz''s Ch. 23)'),
    (v_topic_id, '55: "Aortic Dissection" - Type B?', '["Distal to Subclavian origin", "Managed medically (BP control) usually", "Both", "None"]', 2, 'Stanford Classification. (de Virgilio Ch. 22)'),
    (v_topic_id, '56: "Carotid artery" - Internal? ', '["No branches in the neck", "Supplies brain", "Both", "None"]', 2, 'Anatomy. (Mont Reid Ch. 8)'),
    (v_topic_id, '57: "Carotid artery" - External? ', '["Has branches (Superior Thyroid is #1)", "Supplies face", "Both", "None"]', 2, 'Anatomy. (Schwartz''s Ch. 23)'),
    (v_topic_id, '58: "Carotid Body Tumor" (Chemodectoma) - location?', '["Bifurcation", "Highly vascular", "Both", "None"]', 2, '"Lyre sign" on imaging. (de Virgilio Ch. 23)'),
    (v_topic_id, '59: "Subclavian Steal Syndrome" is caused by stenosis of the subclavian artery ____ to the vertebral artery origin.', '["Distal", "Proximal", "Lateral", "None"]', 1, 'Reversed flow in vertebral artery to supply arm. (Mont Reid Ch. 8)'),
    (v_topic_id, '50: "Phlegmasia Cerulea Dolens" is a severe form of DVT characterized by massive edema and ____.', '["Cyanosis", "Pallor", "Fever", "None"]', 0, 'Surgical emergency due to risk of venous gangrene. (Schwartz''s Ch. 23)'),
    (v_topic_id, '61: "FMD" - location in renal artery?', '["Origin", "Distal 2/3 and branches", "Both", "None"]', 1, 'Contrast with atherosclerosis. (de Virgilio Ch. 23)'),
    (v_topic_id, '62: "Mesenteric Ischemia" - Acute Embolus? ', '["Sudden onset", "SMA #1", "Both", "None"]', 2, 'History. (Mont Reid Ch. 8)'),
    (v_topic_id, '63: "Mesenteric Ischemia" - Chronic? ', '["2 of 3 vessels affected", "Pain after eating", "Both", "None"]', 2, 'History. (Schwartz''s Ch. 23)'),
    (v_topic_id, '64: "AAA" - Rupture risk per year for 6 cm?', '["1%", "10-20%", "50%", "None"]', 1, 'Increases exponentially with size. (de Virgilio Ch. 22)'),
    (v_topic_id, '65: "AAA" - most common bug for Mycotic aneurysm?', '["E. coli", "Salmonella / Staph", "Virus", "None"]', 1, 'Infected aneurysm. (Mont Reid Ch. 8)'),
    (v_topic_id, '66: "Aortoenteric fistula" - triad? ', '["Prior AAA repair, GI bleed, Sepsis", "True", "Both", "None"]', 2, 'Classic surgical board topic. (Schwartz''s Ch. 23)'),
    (v_topic_id, '67: "ABI" > 1.3? ', '["Normal", "Non-compressible vessels (calcified) in diabetics", "Severe PAD", "None"]', 1, 'Need Toe-Brachial Index (TBI). (de Virgilio Ch. 24)'),
    (v_topic_id, '68: "Claudication" - Calves? ', '["Femoral-Popliteal disease", "Aorta", "None", "None"]', 0, 'Most common site. (Mont Reid Ch. 8)'),
    (v_topic_id, '69: "Claudication" - Thighs/Buttocks? ', '["Aortoiliac disease", "Popliteal", "None", "None"]', 0, 'Leriche link. (Schwartz''s Ch. 23)'),
    (v_topic_id, '70: "Ischemic Rest Pain" - improves with?', '["Elevation", "Dependency (hanging foot off bed)", "Heat", "None"]', 1, 'Gravity helps perfusion. (de Virgilio Ch. 24)'),
    (v_topic_id, '71: "Compartment Syndrome" - pressure? ', '["Normal 0-10", "Danger > 30 mmHg or within 30 of diastolic", "Both", "None"]', 2, 'Needs Fasciotomy. (Mont Reid Ch. 8)'),
    (v_topic_id, '72: "Post-ischemic reperfusion" - concern?', '["Hyperkalemia, Myoglobinuria, Acidosis", "Both", "None", "None"]', 0, 'Metabolic wash-out. (Schwartz''s Ch. 23)'),
    (v_topic_id, '73: "Endovascular" - PTA? ', '["Percutaneous Transluminal Angioplasty (Ballooning)", "True", "Both", "None"]', 2, 'Intervention. (de Virgilio Ch. 24)'),
    (v_topic_id, '74: "Iliac artery" - stent? ', '["Excellent patency", "Both", "None", "None"]', 0, 'Large vessel success. (Mont Reid Ch. 8)'),
    (v_topic_id, '75: "Lower extremity" - Vein of choice for bypass?', '["GSV (Great Saphenous)", "SSV", "Cephalic", "None"]', 0, 'The gold standard. (Schwartz''s Ch. 23)'),
    (v_topic_id, '76: "Deep Vein Thrombosis" - calf vs proximal? ', '["Proximal (Popliteal/Femoral) more likely to embolize", "Both", "None", "None"]', 0, 'Risk. (de Virgilio Ch. 25)'),
    (v_topic_id, '77: "Pulmonary Embolism" - most common EKG finding?', '["S1Q3T3", "Sinus tachycardia", "AFib", "None"]', 1, 'S1Q3T3 is classic but rare. (Mont Reid Ch. 8)'),
    (v_topic_id, '78: "IVC Filter" - indication? ', '["PE with contraindication to anticoagulation", "Recurrent PE on therapy", "Both", "None"]', 2, 'Guidelines. (Schwartz''s Ch. 24)'),
    (v_topic_id, '79: "Warfarin" - mechanism? ', '["Inhibits Vitamin K epoxide reductase", "Factors II, VII, IX, X", "Both", "None"]', 2, 'Anticoagulation. (de Virgilio Ch. 1)'),
    (v_topic_id, '80: "Warfarin" - bridge? ', '["Start Heparin first", "Avoid Protein C/S induced skin necrosis", "Both", "None"]', 2, 'Safety. (Mont Reid Ch. 8)'),
    (v_topic_id, '81: "Venous Ulcer" - appearance?', '["Shallow, irregular borders, medial", "Both", "None", "None"]', 0, 'Clinical sign. (Schwartz''s Ch. 24)'),
    (v_topic_id, '82: "Arterial Ulcer" - appearance?', '["Deep, punched out, distal", "Both", "None", "None"]', 0, 'Clinical sign. (de Virgilio Ch. 24)'),
    (v_topic_id, '83: "Diabetic Ulcer" - location?', '["Pressure points (Plantar surface)", "Both", "None", "None"]', 0, 'Neuropathic. (Mont Reid Ch. 8)'),
    (v_topic_id, '84: "AV fistula" - Maturation? ', '["Rule of 6s: 6 weeks, 6 mm wide, 6 mm deep, 600 mL/min flow", "Both", "None", "None"]', 2, 'Access. (Schwartz''s Ch. 23)'),
    (v_topic_id, '85: "AV Graft" - concern? ', '["Higher infection/thrombosis risk than fistula", "True", "Both", "None"]', 2, 'Access. (de Virgilio Ch. 26)'),
    (v_topic_id, '86: "Subclavian artery" - branches? ', '["Vertebral, Thyrocervical, Internal Mammary, Costocervical", "All", "None", "None"]', 1, 'Anatomy. (Mont Reid Ch. 8)'),
    (v_topic_id, '87: "Axillary artery" - boundaries? ', '["1st rib to Teres major", "Both", "None", "None"]', 0, 'Anatomy. (Schwartz''s Ch. 23)'),
    (v_topic_id, '88: "Brachial artery" - divides at?', '["Antecubital fossa into Radial/Ulnar", "True", "Both", "None"]', 2, 'Anatomy. (de Virgilio Ch. 23)'),
    (v_topic_id, '89: "Allen Test" - purpose? ', '["Checks patency of Radial and Ulnar arteries (for ABG or harvest)", "Both", "None", "None"]', 2, 'Clinical skill. (Mont Reid Ch. 8)'),
    (v_topic_id, '90: "Adson Test" - TOS? ', '["Loss of radial pulse with head rotation/extension", "Both", "None", "None"]', 0, 'Physical exam. (Schwartz''s Ch. 23)'),
    (v_topic_id, '91: "Raynaud''s" - colors? ', '["White (ischemia), Blue (cyanosis), Red (hyperemia)", "Both", "None", "None"]', 2, 'Triphasic. (de Virgilio Ch. 23)'),
    (v_topic_id, '92: "Buerger''s" - demographic? ', '["Young male smokers", "Both", "None", "None"]', 0, 'Epidemiology. (Mont Reid Ch. 8)'),
    (v_topic_id, '93: "Takayasu Arteritis" = ?', '["Pulseless disease", "Large vessel vasculitis (Aorta/branches)", "Young Asian females", "All"]', 3, 'Autoimmune. (Schwartz''s Ch. 23)'),
    (v_topic_id, '94: "Giant Cell Arteritis" (Temporal) - risk? ', '["Blindness", "Needs high dose steroids", "Both", "None"]', 2, 'Emergency. (de Virgilio Ch. 23)'),
    (v_topic_id, '95: "SMA Syndrome" vs "Mesenteric Ischemia"?', '["SMA syndrome is compression of duodenum", "Both", "None", "None"]', 0, 'Clarification. (Mont Reid Ch. 8)'),
    (v_topic_id, '96: "Celiac artery" - branches? ', '["Left Gastric, Splenic, Common Hepatic", "All", "None", "None"]', 1, 'Anatomy. (Schwartz''s Ch. 23)'),
    (v_topic_id, '97: "IMA" - artery of Drummond? ', '["Collateral with SMA", "Both", "None", "None"]', 0, 'Anatomy. (de Virgilio Ch. 22)'),
    (v_topic_id, '98: "AAA" - most common bug for Graft infection?', '["Staph epidermidis", "Staph aureus", "None", "None"]', 0, 'Biofilm. (Mont Reid Ch. 8)'),
    (v_topic_id, '99: "Venous mapping" - US? ', '["Check diameter/patency of GSV before bypass", "True", "Both", "None"]', 2, 'Pre-op. (Schwartz''s Ch. 23)'),
    (v_topic_id, '100: "Varicose veins" - Saphenofemoral junction? ', '["Site of most reflux", "True", "Both", "None"]', 2, 'Anatomy. (de Virgilio Ch. 25)');
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: "Internal Iliac" (Hypogastric) - significance?', '["Supplies pelvis / erectile function", "True", "Both", "None"]', 2, 'Anatomy. (Schwartz''s Ch. 23)'),
