    (v_topic_id, '119: "CEA" - patch? ', '["Dacron or Vein patch used to widen artery", "Reduces restenosis", "Both", "None"]', 2, 'Technique. (Schwartz''s Ch. 23)'),
    (v_topic_id, '120: "CEA" - Nerve injury? ', '["Vagus (Recurrent) - hoarse", "Hypoglossal - tongue deviation", "Both", "None"]', 2, 'Complication. (de Virgilio Ch. 23)'),
    (v_topic_id, '121: "Subclavian steal" - exercise? ', '["Arm exercise causes vertigo/syncope", "Both", "None", "None"]', 0, 'Symptoms. (Mont Reid Ch. 8)'),
