    (v_topic_id, '124: "Renal artery" - stent? ', '["Better for atherosclerosis than FMD", "True", "Both", "None"]', 2, 'Management. (Mont Reid Ch. 8)'),
    (v_topic_id, '125: "PAD" - CLI? ', '["Rest pain / Gangrene / ABI < 0.4", "Both", "None", "None"]', 0, 'Definition. (Schwartz''s Ch. 23)'),
