    (v_topic_id, '140: "Vascular" - PTFE? ', '["Synthetic graft (Gore-Tex)", "Both", "None", "None"]', 0, 'Material. (Schwartz''s Ch. 23)'),
    (v_topic_id, '141: "Vascular" - Dacron? ', '["Synthetic graft (Polyester)", "Used for large vessels", "Both", "None"]', 2, 'Material. (de Virgilio Ch. 22)'),
